// Puja Paddhati: step-by-step puja vidhi for the home. Written in the common Smarta/North-Indian household form unless a
// region or sampradaya is named; families and Pandits follow their own kula-parampara, which always takes precedence.
// Mantras are the standard, widely printed ones; a `slug` links to the mantra page (with audio / chant-along).

export type PCat = 'general' | 'deity' | 'festival' | 'region' | 'community';
export interface PStep { en: string; hi: string; doEn: string; doHi: string; mantra?: string; slug?: string; }
export interface Paddhati {
  id: string; cat: PCat; icon: string; en: string; hi: string;
  /** Region or sampradaya label, e.g. "Bihar · Jharkhand · East UP". */
  tag?: string; tagHi?: string;
  when: string; whenHi: string;
  aboutEn: string; aboutHi: string;
  /** Samagri list id on the Samagri page, if there is one. */
  samagri?: string;
  /** Puja name in the Pandit booking list, for "Book a Pandit". */
  book?: string;
  steps: PStep[];
  /** Added by the admin (stored in Firestore). */
  custom?: boolean;
}
export const CATS: { id: PCat; en: string; hi: string; icon: string }[] = [
  { id: 'general', en: 'General', hi: 'सामान्य', icon: '🪔' },
  { id: 'deity', en: 'By deity', hi: 'देवता अनुसार', icon: '🕉️' },
  { id: 'festival', en: 'Festivals', hi: 'पर्व-त्योहार', icon: '🎉' },
  { id: 'region', en: 'Regional', hi: 'क्षेत्रीय', icon: '🗺️' },
  { id: 'community', en: 'Sampradaya', hi: 'संप्रदाय', icon: '📿' },
];

const s = (en: string, hi: string, doEn: string, doHi: string, mantra?: string, slug?: string): PStep => ({ en, hi, doEn, doHi, mantra, slug });

// ---------------------------------------------------------------- shared steps
const ACHAMAN = s('Purify and sip water (Pavitrikaran, Achamana)', 'पवित्रीकरण व आचमन',
  'Bathe and wear clean clothes. Sit on an asana facing east or north. Sprinkle a little water on yourself and the samagri with a flower, then sip water three times from the right palm.',
  'स्नान कर स्वच्छ वस्त्र पहनें। पूर्व या उत्तर की ओर मुख करके आसन पर बैठें। फूल से अपने ऊपर व सामग्री पर जल छिड़कें, फिर दाहिनी हथेली से तीन बार आचमन करें।',
  'ॐ अपवित्रः पवित्रो वा सर्वावस्थां गतोऽपि वा।\nयः स्मरेत् पुण्डरीकाक्षं स बाह्याभ्यन्तरः शुचिः॥\nॐ केशवाय नमः। ॐ नारायणाय नमः। ॐ माधवाय नमः।', 'apavitrah-pavitro-va');
const DEEP = s('Light the lamp', 'दीप प्रज्वलन',
  'Light a ghee or sesame-oil diya on the right side of the deity and a dhoop or agarbatti on the left. Fold hands to the flame.',
  'देवता के दाहिनी ओर घी या तिल के तेल का दीपक और बाईं ओर धूप-अगरबत्ती जलाएँ। ज्योति को प्रणाम करें।',
  'शुभं करोति कल्याणम् आरोग्यं धनसम्पदः।\nशत्रुबुद्धिविनाशाय दीपज्योतिर्नमोऽस्तु ते॥', 'deepa-jyoti');
const SANKALP = (forEn: string, forHi: string, sa: string) => s('Take the sankalp (resolve)', 'संकल्प',
  `Hold water, akshat (unbroken rice), a flower and a coin in the right hand. Say the date, place, your gotra and name, and that you are doing ${forEn}; then let it fall in a plate.`,
  `दाहिने हाथ में जल, अक्षत, फूल और सिक्का लें। तिथि, स्थान, अपना गोत्र व नाम बोलकर कहें कि आप ${forHi} कर रहे हैं; फिर इसे थाली में छोड़ दें।`,
  `ॐ विष्णुर्विष्णुर्विष्णुः। अद्य ____ मासे ____ पक्षे ____ तिथौ ____ वासरे,\n____ गोत्रः ____ नामाहं ${sa} यथाशक्ति पूजनं करिष्ये॥`);
const GANESH = s('Remember Shri Ganesh first', 'श्री गणेश स्मरण',
  'Every puja begins with Ganesha. Offer a flower and akshat to Ganesha (an idol, or a betel nut with mauli tied on it).',
  'हर पूजा श्री गणेश से आरंभ होती है। गणेश जी (मूर्ति, या मौली लपेटी सुपारी) को फूल व अक्षत अर्पित करें।',
  'वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥', 'vakratunda');
const KALASH = s('Kalash sthapana', 'कलश स्थापना',
  'Fill a copper or brass kalash with water; add a betel nut, coin, akshat and a little Gangajal. Place 5 mango leaves at the mouth and a coconut wrapped in red cloth on top. Draw a swastik on it with roli and tie mauli.',
  'तांबे या पीतल के कलश में जल भरें; उसमें सुपारी, सिक्का, अक्षत और थोड़ा गंगाजल डालें। मुख पर आम के 5 पत्ते और ऊपर लाल कपड़े में लिपटा नारियल रखें। रोली से स्वस्तिक बनाकर मौली बाँधें।',
  'कलशस्य मुखे विष्णुः कण्ठे रुद्रः समाश्रितः।\nमूले तत्र स्थितो ब्रह्मा मध्ये मातृगणाः स्मृताः॥\nगङ्गे च यमुने चैव गोदावरि सरस्वति।\nनर्मदे सिन्धु कावेरि जलेऽस्मिन् सन्निधिं कुरु॥', 'ganga-cha-yamune');
const KSHAMA = s('Ask forgiveness and conclude', 'क्षमा प्रार्थना व विसर्जन',
  'With folded hands ask forgiveness for any mistake in the puja. Offer a last flower, then distribute prasad to everyone.',
  'हाथ जोड़कर पूजा में हुई किसी भी भूल के लिए क्षमा माँगें। अंतिम पुष्प अर्पित करें, फिर सबको प्रसाद बाँटें।',
  'आवाहनं न जानामि न जानामि विसर्जनम्।\nपूजां चैव न जानामि क्षमस्व परमेश्वर॥\nमन्त्रहीनं क्रियाहीनं भक्तिहीनं सुरेश्वर।\nयत्पूजितं मया देव परिपूर्णं तदस्तु मे॥', 'kshama-prarthana');
const PUSHPANJALI = s('Pradakshina and pushpanjali', 'प्रदक्षिणा व पुष्पांजलि',
  'Turn clockwise around the deity (or in place) and offer flowers with both hands joined.',
  'देवता की (या अपने स्थान पर ही) दक्षिणावर्त परिक्रमा करें और दोनों हाथों से पुष्पांजलि दें।',
  'यानि कानि च पापानि जन्मान्तरकृतानि च।\nतानि तानि विनश्यन्ति प्रदक्षिण पदे पदे॥');

/** The 16 upacharas, grouped into steps, for a deity whose name-mantra is `nm` (e.g. "श्री गणेशाय"). */
function upachara(nm: string, en: string, hi: string, snanaEn = 'water, then panchamrit (milk, curd, ghee, honey, sugar), then clean water', snanaHi = 'जल, फिर पंचामृत (दूध, दही, घी, शहद, शक्कर), फिर शुद्ध जल'): PStep[] {
  return [
    s(`Invoke ${en} (Dhyana, Avahana, Asana)`, `${hi} का ध्यान, आवाहन व आसन`,
      `Close your eyes and picture ${en}. Offer akshat to invite the deity, and a flower as the seat.`,
      `आँखें बंद कर ${hi} का ध्यान करें। अक्षत से आवाहन करें और पुष्प से आसन दें।`,
      `ॐ ${nm} नमः। ध्यायामि। आवाहयामि। आसनं समर्पयामि॥`),
    s('Water for feet, hands and sipping (Padya, Arghya, Achamaniya)', 'पाद्य, अर्घ्य, आचमनीय',
      'Offer a spoon of water each: to the feet, to the hands (with akshat and flower), and for sipping.',
      'एक-एक चम्मच जल अर्पित करें: चरणों में, हाथों में (अक्षत-पुष्प सहित), और आचमन के लिए।',
      `ॐ ${nm} नमः। पाद्यं समर्पयामि। अर्घ्यं समर्पयामि। आचमनीयं समर्पयामि॥`),
    s('Bath (Snana)', 'स्नान', `Bathe the idol with ${snanaEn}. (For a picture, sprinkle with a flower.) Wipe dry.`,
      `मूर्ति को ${snanaHi} से स्नान कराएँ। (चित्र हो तो पुष्प से छींटे दें।) पोंछकर सुखाएँ।`,
      `ॐ ${nm} नमः। पञ्चामृतस्नानं समर्पयामि। शुद्धोदकस्नानं समर्पयामि॥`),
    s('Clothes, sacred thread, chandan, akshat, flowers', 'वस्त्र, यज्ञोपवीत, चंदन, अक्षत, पुष्प',
      'Offer cloth or mauli, janeu (for gods), chandan or roli tilak, akshat, flowers and garland. Each deity has a favourite: durva for Ganesha, bilva for Shiva, tulsi for Vishnu, red flowers for Devi.',
      'वस्त्र या मौली, यज्ञोपवीत (देवताओं को), चंदन या रोली का तिलक, अक्षत, फूल व माला अर्पित करें। हर देवता का प्रिय: गणेश को दूर्वा, शिव को बिल्वपत्र, विष्णु को तुलसी, देवी को लाल फूल।',
      `ॐ ${nm} नमः। वस्त्रं समर्पयामि। यज्ञोपवीतं समर्पयामि। गन्धं समर्पयामि। अक्षतान् समर्पयामि। पुष्पाणि समर्पयामि॥`),
    s('Incense and lamp (Dhoopa, Deepa)', 'धूप व दीप', 'Wave the dhoop, then the lamp, in front of the deity.',
      'देवता के सामने धूप और फिर दीपक दिखाएँ।', `ॐ ${nm} नमः। धूपम् आघ्रापयामि। दीपं दर्शयामि॥`),
    s('Food offering (Naivedya), paan and dakshina', 'नैवेद्य, तांबूल व दक्षिणा',
      'Offer prasad (fruit, sweets) with a tulsi leaf or a drop of water on it, then water for sipping, a betel leaf with supari, and dakshina.',
      'प्रसाद (फल, मिठाई) पर तुलसी दल या जल की बूँद रखकर अर्पित करें, फिर आचमन जल, पान-सुपारी और दक्षिणा।',
      `ॐ ${nm} नमः। नैवेद्यं निवेदयामि। ताम्बूलं समर्पयामि। दक्षिणां समर्पयामि॥`),
  ];
}
const AARTI = (slug?: string, en = 'Aarti', hi = 'आरती') => s(en, hi,
  'Light camphor or a ghee lamp in the aarti thali and wave it clockwise while everyone sings the aarti; ring the bell. Then offer the aarti to all present.',
  'आरती की थाली में कपूर या घी का दीपक जलाकर दक्षिणावर्त घुमाएँ, सब मिलकर आरती गाएँ और घंटी बजाएँ। फिर सबको आरती दें।',
  'कर्पूरगौरं करुणावतारं संसारसारं भुजगेन्द्रहारम्।\nसदा वसन्तं हृदयारविन्दे भवं भवानीसहितं नमामि॥', slug);
const FULL = (nm: string, en: string, hi: string, forEn: string, forHi: string, forSa: string, aarti?: string, extra: PStep[] = []) =>
  [ACHAMAN, DEEP, SANKALP(forEn, forHi, forSa), GANESH, ...upachara(nm, en, hi), ...extra, AARTI(aarti), PUSHPANJALI, KSHAMA];

